// Learner test accounts, read from the CSV named by ACCOUNTS_CSV (header: email,password).
// The CSV is generated by packages/db/src/seed-loadtest-accounts.ts outside the repository and is never committed.
import { SharedArray } from "k6/data";
// `open` is an init-context global in k6, not an export of the k6 module.

const file = __ENV.ACCOUNTS_CSV;
if (!file) {
  throw new Error("ACCOUNTS_CSV is required: path to the CSV written by seed-loadtest-accounts.ts");
}

const accounts = new SharedArray("learner accounts", () => {
  const lines = open(file)
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("#"));
  const [header, ...rows] = lines;
  if (header !== "email,password") {
    throw new Error(`ACCOUNTS_CSV must start with the header "email,password" (got "${header}")`);
  }
  return rows.map((row) => {
    const [email, password] = row.split(",");
    return { email, password };
  });
});

if (accounts.length === 0) {
  throw new Error("ACCOUNTS_CSV contains no accounts");
}

// Each VU gets its own account; with fewer accounts than VUs the accounts are shared round-robin.
export function accountForVu() {
  return accounts[(__VU - 1) % accounts.length];
}
